def sort_by_frequency(arr):
    frequency = {}
    for num in arr:
        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1

    sorted_arr = sorted(arr, key=lambda x: (frequency[x], x))
    return sorted_arr

